CREATE OR REPLACE PROCEDURE sp(arg1 integer, arg2 text, arg3 text, arg4 integer, arg5 text, arg6 integer)
LANGUAGE plpgsql
AS $$
DECLARE
    v_threshold integer := arg1;
    v_status text := arg2;
    v_operation text := arg3;
    v_handled_count integer := 0;
    v_batch_size integer := 10;
    v_state text := 'INIT';
    v_high_priority_seen boolean := false;
    v_mode text;
    v_rid integer;
    v_rname text;
    v_address text;
    v_sid integer;
    v_lname text;
    v_citycode text;
    v_sex text;
    v_rk_id integer;
    v_priority text;
BEGIN
    -- Pick the mode from the initial threshold
    IF arg1 < 3 THEN
        v_mode := 'MINIMAL_PROCESS';
        v_state := 'MINIMAL_PROCESS';

        FOR v_rid, v_rname, v_address IN
            SELECT "ResID", "ResName", "Address"
            FROM "Restaurant"
            WHERE "ResID" < arg1
              AND "ResName" LIKE arg2
            ORDER BY "ResID"
        LOOP
            v_handled_count := v_handled_count + 1;

            IF v_rid > 25 THEN
                UPDATE "Restaurant"
                SET "ResName" = 'PROMOTED'
                WHERE "ResID" = v_rid;
            ELSIF v_address = v_operation THEN
                DELETE FROM "Visits_Restaurant"
                WHERE "ResID" = v_rid;

                DELETE FROM "Type_Of_Restaurant"
                WHERE "ResID" = v_rid;

                DELETE FROM "Restaurant"
                WHERE "ResID" = v_rid
                  AND "ResName" = v_rname;
            ELSE
                UPDATE "Restaurant"
                SET "Address" = 'PENDING'
                WHERE "ResID" = v_rid;
            END IF;

            IF v_handled_count >= v_batch_size THEN
                v_batch_size := v_batch_size + 5;
            END IF;
        END LOOP;

    ELSIF arg1 < 8 THEN
        v_mode := 'STANDARD_PROCESS';
        v_state := 'STANDARD_PROCESS';

        FOR v_sid, v_lname, v_citycode IN
            SELECT "StuID", "LName", "city_code"
            FROM "Student"
            WHERE "StuID" BETWEEN arg4 - 5 AND arg4 + 15
            ORDER BY "StuID"
        LOOP
            v_handled_count := v_handled_count + 1;

            IF v_citycode = v_operation THEN
                UPDATE "Student"
                SET "Sex" = 'U'
                WHERE "StuID" = v_sid;
            END IF;

            IF v_lname = arg5 THEN
                UPDATE "Student"
                SET "city_code" = 'MATCHED'
                WHERE "StuID" = v_sid;
            END IF;

            IF v_lname LIKE 'ACTIVE%' THEN
                UPDATE "Student"
                SET "LName" = 'PROCESSED'
                WHERE "StuID" = v_sid;
            ELSIF v_sid > arg4 + 5 THEN
                v_threshold := v_threshold + v_sid;
            ELSE
                DELETE FROM "Student"
                WHERE "StuID" = v_sid
                  AND "LName" = 'EXPIRED';
            END IF;

            IF v_handled_count >= v_batch_size THEN
                v_batch_size := v_batch_size + 5;
            END IF;
        END LOOP;

    ELSIF arg1 < 18 THEN
        v_mode := 'ENHANCED_PROCESS';
        v_state := 'ENHANCED_PROCESS';

        FOR v_rk_id IN
            SELECT "ResTypeID"
            FROM "Restaurant_Type"
            WHERE "ResTypeID" > arg6 - 20
            ORDER BY "ResTypeID"
        LOOP
            v_handled_count := v_handled_count + 1;

            IF v_rk_id < 50 THEN
                v_priority := 'LOW_PRIORITY';
            ELSIF v_rk_id < 150 THEN
                v_priority := 'MEDIUM_PRIORITY';
            ELSE
                v_priority := 'HIGH_PRIORITY';
            END IF;

            IF v_priority = 'HIGH_PRIORITY' THEN
                v_high_priority_seen := true;
            END IF;

            UPDATE "Restaurant_Type"
            SET "ResTypeID" = "ResTypeID" + 10
            WHERE "ResTypeID" = v_rk_id;

            IF v_handled_count >= v_batch_size THEN
                v_batch_size := v_batch_size + 5;
            END IF;
        END LOOP;

    ELSIF arg1 < 25 THEN
        v_mode := 'ARCHIVE_MODE';
        v_state := 'ARCHIVE_MODE';

        UPDATE "Restaurant"
        SET "Address" = 'ARCHIVED'
        WHERE "ResID" < arg1
          AND "ResName" <> v_status;

    ELSIF arg1 < 40 THEN
        v_mode := 'CLEANUP_MODE';
        v_state := 'CLEANUP_MODE';

        DELETE FROM "Student"
        WHERE "StuID" < arg4
          AND "LName" = 'OBSOLETE';

    ELSE
        v_mode := 'BOOST_MODE';
        v_state := 'BOOST_MODE';

        UPDATE "Restaurant_Type"
        SET "ResTypeID" = arg6 + 100
        WHERE "ResTypeID" > 200;

    END IF;

    -- Final action: only the first applicable one
